import express from 'express';

const DASHBOARD_FUNCTION = Buffer.from('', 'base64').toString('utf8');
const PREMIUM_DASHBOARD_CSS = Buffer.from('', 'base64').toString('utf8');

const originalSend = express.response.send;

express.response.send = function patchedSend(body) {
  try {
    const requestPath = this.req?.path || this.req?.url || '';

    if (typeof body === 'string' && requestPath.startsWith('/app.js')) {
      const start = body.indexOf('function renderDashboard()');
      const end = body.indexOf('\nfunction renderDisbursedLoans', start);

      if (start !== -1 && end !== -1) {
        body = body.slice(0, start) + DASHBOARD_FUNCTION + body.slice(end);
      }
    }

    if (typeof body === 'string' && requestPath.startsWith('/app.css')) {
      body += '\n' + PREMIUM_DASHBOARD_CSS + '\n';
    }
  } catch (_) {}

  return originalSend.call(this, body);
};
